package com.tapeverify.copilot.controller;
import com.tapeverify.copilot.dto.*; import com.tapeverify.copilot.entity.AppUser; import com.tapeverify.copilot.repository.UserRepository; import jakarta.validation.Valid; import java.time.LocalDateTime; import java.util.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/users") public class AdminUserController {private final UserRepository users;private final PasswordEncoder passwords;public AdminUserController(UserRepository users,PasswordEncoder passwords){this.users=users;this.passwords=passwords;}@GetMapping public List<UserDto> list(){return users.findAll().stream().map(this::dto).toList();}@PostMapping public ResponseEntity<UserDto> create(@Valid @RequestBody CreateUserDto in){if(users.findByUsername(in.getUsername().trim()).isPresent())throw new IllegalArgumentException("Username already exists");var u=users.save(AppUser.builder().username(in.getUsername().trim()).passwordHash(passwords.encode(in.getPassword())).role(in.getRole()).active(true).createdAt(LocalDateTime.now()).build());return ResponseEntity.status(HttpStatus.CREATED).body(dto(u));}private UserDto dto(AppUser u){return UserDto.builder().id(u.getId()).username(u.getUsername()).role(u.getRole().name()).active(u.isActive()).createdAt(u.getCreatedAt()).build();}}
